package szserver;
import szserver.net.*;import szserver.client.*;import java.nio.*;import java.nio.file.*;import java.io.*;import java.lang.reflect.*;
/** Installed actor registry and corpse decoder, including Bullet's native 20 Hz inherited-velocity contract. */
public final class CorpseHandoffTests {
 public static void main(String[] args)throws Exception {
  try(var codecs=new ClientPackets(Path.of(args[0]))){
   Field lf=ClientPackets.class.getDeclaredField("loader");lf.setAccessible(true);var loader=(ClassLoader)lf.get(codecs);var add=java.net.URLClassLoader.class.getDeclaredMethod("addURL",java.net.URL.class);add.setAccessible(true);add.invoke(loader,Path.of(args[0]).getParent().resolve("server-java/fixtures/native-resources").toUri().toURL());var registry=Class.forName("423259911",true,loader);registry.getMethod("assert").invoke(null);
   var unsafeType=Class.forName("sun.misc.Unsafe");Field uf=unsafeType.getDeclaredField("theUnsafe");uf.setAccessible(true);Object unsafe=uf.get(null);Class<?> vector=Class.forName("153304200",true,loader),base=Class.forName("544082630",true,loader);int checks=0;
   for(String skin:new String[]{null,"universal_01","zombie_01"})for(int source:new int[]{0,42}){
    double[] speed={8,-2,2.5};byte[] body=Wire.readFrame(new ByteArrayInputStream(GamePackets.corpse(1000001,source,"pose",new double[]{1,90,3},123,speed,null,new double[3],null,skin)));ByteBuffer b=ByteBuffer.wrap(body);if(Wire.varint(b)!=5)throw new AssertionError("dynamic corpse");var in=new DataInputStream(new ByteArrayInputStream(body,b.position(),b.remaining()));if(!in.readUTF().equals("1510484702"))throw new AssertionError("spawn class");int type=in.readUnsignedByte();Class<?> nativeType=(Class<?>)registry.getMethod("float",int.class).invoke(null,type);String expected=skin==null?"904579751":"1130225430";if(!nativeType.getName().equals(expected))throw new AssertionError("corpse native type "+nativeType);in.skipNBytes(18);int size=Wire.varint(ByteBuffer.wrap(in.readAllBytes()));
    // Decode envelope first to get the actual native subtype bytes.
    Object spawn=Class.forName("1510484702",true,loader).getConstructor().newInstance();var payload=new DataInputStream(new ByteArrayInputStream(body,b.position()+2+"1510484702".length(),body.length-b.position()-2-"1510484702".length()));spawn.getClass().getMethod("extends",DataInput.class).invoke(spawn,payload);byte[] raw=(byte[])spawn.getClass().getSuperclass().getField("break").get(spawn);
    Object corpse=unsafeType.getMethod("allocateInstance",Class.class).invoke(unsafe,nativeType);for(Field f:nativeType.getFields())if(f.getType()==vector&&!Modifier.isStatic(f.getModifiers())){f.setAccessible(true);f.set(corpse,vector.getConstructor().newInstance());}
    var input=new DataInputStream(new ByteArrayInputStream(raw));nativeType.getMethod("const",DataInput.class).invoke(corpse,input);if(input.available()!=0)throw new AssertionError("unparsed corpse tail");if(base.getField("continue").getFloat(corpse)!=GamePackets.corpseYaw(123))throw new AssertionError("corpse model heading lost");if(base.getField("case").getInt(corpse)!=source)throw new AssertionError("source actor lost");Object velocity=base.getField("while").get(corpse);String[] xyz={"case","void","import"};for(int i=0;i<3;i++)if(Math.abs(vector.getField(xyz[i]).getDouble(velocity)*20-speed[i])>1e-5)throw new AssertionError("native Bullet velocity scaled incorrectly");checks++;
   }
   Class<?> quaternion=Class.forName("600627034",true,loader),math=Class.forName("982660287",true,loader);String[] components={"public","implements","float","catch"};
   for(float heading:new float[]{0,45,90,135,180,225,270,315,359,-90,-180,720}){
    Object live=quaternion.getConstructor().newInstance(),dead=quaternion.getConstructor().newInstance();quaternion.getMethod("protected",float.class).invoke(live,(float)Math.toRadians(180-heading));math.getMethod("import",quaternion,float.class,float.class,float.class).invoke(null,dead,0f,-GamePackets.corpseYaw(heading),0f);double dot=0;for(String component:components)dot+=quaternion.getField(component).getFloat(live)*quaternion.getField(component).getFloat(dead);if(Math.abs(Math.abs(dot)-1)>1e-5)throw new AssertionError("native corpse world basis flips heading "+heading+" dot="+dot);checks++;
   }
   var turned=new PlayerAnimationPackets.State(0,0,0,0,true,0,0,0,0,false,0,0,0,0,null,null).pose(new PlayerAnimationPackets.Pose(90,0,0));float bodyHeading=PlayerAnimationPackets.bodyHeading(PlayerAnimationPackets.component(turned),0);if(Math.abs(bodyHeading-90)>1.5||Math.abs(bodyHeading)<45)throw new AssertionError("camera angle substituted for native body angle");if(Math.abs(PlayerAnimationPackets.bodyHeading(PlayerAnimationPackets.component(turned),90)-180)>1.5)throw new AssertionError("actor world rotation omitted");if(PlayerAnimationPackets.bodyHeading(new byte[0],33)!=33)throw new AssertionError("legacy pose fallback");
   System.out.println("PASS 6 native player/HumanMale corpse decodes and 12 native model/Bullet heading checks; local/remote source and inherited velocity");
  }
 }
}
